# Let me create some test images with potential triggers to find the backdoor
# The trigger is a 3-5 pixel patch, 1 pixel from a corner
# Let me test with white square triggers on a few clean images

def add_trigger(img, corner='tl', size=3, pattern='white'):
    """Add trigger to image. img is (3,32,32) uint8"""
    img = img.clone()
    if corner == 'tl':
        r, c = 1, 1
    elif corner == 'tr':
        r, c = 1, 32 - 1 - size
    elif corner == 'bl':
        r, c = 32 - 1 - size, 1
    elif corner == 'br':
        r, c = 32 - 1 - size, 32 - 1 - size
    else:
        raise ValueError(f"Unknown corner: {corner}")

    if pattern == 'white':
        img[:, r:r+size, c:c+size] = 255
    elif pattern == 'checkerboard':
        for i in range(size):
            for j in range(size):
                val = 255 if (i + j) % 2 == 0 else 0
                img[:, r+i, c+j] = val
    elif pattern == 'random':
        # Use fixed random pattern
        torch.manual_seed(42)
        noise = torch.randint(0, 256, (3, size, size), dtype=torch.uint8)
        img[:, r:r+size, c:c+size] = noise
    return img

